}
function addTitle(slide, title, kicker) {
  if (kicker) slide.addText(kicker.toUpperCase(), { x: 0.62, y: 0.28, w: 5.8, h: 0.22, fontSize: 8.5, bold: true, color: C.blue, charSpace: 1.1, margin: 0 });
  slide.addText(title, { x: 0.6, y: 0.55, w: 11.75, h: 0.55, fontSize: 23, bold: true, color: C.navy, fit: 'shrink', margin: 0.02, breakLine: false });
}
function addRule(slide, x, y, w, color=C.blue) { slide.addShape(pptx.ShapeType.line, { x, y, w, h: 0, line: { color, width: 2 } }); }
function addText(slide, text, x, y, w, h, opts={}) {
  slide.addText(text, { x, y, w, h, fontFace: 'Aptos', fontSize: opts.fontSize || 12, color: opts.color || C.gray700, bold: !!opts.bold, italic: !!opts.italic, align: opts.align || 'left', valign: opts.valign || 'mid', margin: opts.margin === undefined ? 0.04 : opts.margin, breakLine: false, fit: opts.fit || 'shrink', bullet: opts.bullet });
}
function card(slide, x, y, w, h, opts={}) {
  slide.addShape(pptx.ShapeType.roundRect, { x, y, w, h, rectRadius: 0.06, fill: { color: opts.fill || C.white, transparency: opts.transparency || 0 }, line: { color: opts.line || 'E2E8F0', width: opts.width || 0.7 } });
}
function metricCard(slide, x, y, w, h, value, label, color=C.blue, sub='') {
