}
function drawBars(slide, data, x, y, w, h, options={}) {
  const max = options.max || Math.max(...data.map(d => d.value));
  const rowH = h / data.length;
  const labelW = options.labelW || 2.35;
  const valueW = options.valueW || 0.72;
  const barX = x + labelW;
  const barW = w - labelW - valueW;
  data.forEach((d, i) => {
    const cy = y + i * rowH + rowH * 0.18;
    const bh = Math.min(0.31, rowH * 0.58);
    addText(slide, d.name, x, cy-0.01, labelW-0.08, bh+0.08, { fontSize: options.fontSize || 8.2, color: C.gray700, bold: i < (options.boldTop || 0), align: 'right', margin: 0.01 });
    slide.addShape(pptx.ShapeType.rect, { x: barX, y: cy, w: barW, h: bh, fill: { color: C.gray200 }, line: { color: C.gray200, transparency: 100 } });
    slide.addShape(pptx.ShapeType.rect, { x: barX, y: cy, w: barW * (d.value / max), h: bh, fill: { color: d.color || options.color || C.blue }, line: { color: d.color || options.color || C.blue, transparency: 100 } });
    addText(slide, options.format ? options.format(d.value) : `${d.value}%`, barX + barW + 0.12, cy-0.01, valueW, bh+0.08, { fontSize: options.fontSize || 8.2, color: C.gray700, bold: true, margin: 0 });
  });
}
function drawGroupedBars(slide, categories, series, x, y, w, h, opts={}) {
  const max = opts.max || Math.max(...series.flatMap(s => s.values.map(v => v || 0)));
