  slide.addShape(pptx.ShapeType.line, { x: plotX, y: plotY + plotH, w: plotW, h: 0, line: { color: C.gray300, width: 0.8 } });
  [0, max/2, max].forEach(t => {
    const tx = plotX + (t/max)*plotW;
