  const groupH = plotH / categories.length;
  const barH = 0.18;
  categories.forEach((cat, i) => {
    const gy = plotY + i*groupH + groupH*0.2;
    addText(slide, cat, x, gy+0.08, 0.38, 0.18, { fontSize: 7.2, color: C.gray600, align: 'right', margin: 0 });
