      const val = s.values[i];
      if (val === null || val === undefined) return;
      const by = gy + si*(barH+0.05);
      slide.addShape(pptx.ShapeType.rect, { x: plotX, y: by, w: plotW*(val/max), h: barH, fill: { color: s.color }, line: { color: s.color, transparency: 100 } });
