function drawScatter(slide, data, x, y, w, h, cfg={}) {
  const xMin = cfg.xMin ?? Math.min(...data.map(d=>d.x));
  const xMax = cfg.xMax ?? Math.max(...data.map(d=>d.x));
  const yMin = cfg.yMin ?? Math.min(...data.map(d=>d.y));
