  const xticks = cfg.xticks || [xMin, Math.round((xMin+xMax)/2), xMax];
  const yticks = cfg.yticks || [yMin, Math.round((yMin+yMax)/2), yMax];
  xticks.forEach(t=>{
    const tx=px+(t-xMin)/(xMax-xMin)*pw;
    slide.addShape(pptx.ShapeType.line,{x:tx,y:py,w:0,h:ph,line:{color:C.gray200,width:0.45}});
    addText(slide,String(t),tx-0.16,py+ph+0.08,0.32,0.12,{fontSize:6.6,color:C.gray500,align:'center',margin:0});
